8	/**
9	 * A synchronous UDP client used for testing.
10	 */
11	class UdpSyncClient {
12	public:
13	  UdpSyncClient(Network::Address::IpVersion version)
14	      : socket_(std::make_unique<Network::UdpListenSocket>(
15	            Network::Test::getCanonicalLoopbackAddress(version), nullptr, true)) {
16	    // TODO(mattklein123): Right now all sockets are non-blocking. Move this non-blocking
17	    // modification black to the abstraction layer so it will work for multiple platforms.
18	    RELEASE_ASSERT(fcntl(socket_->ioHandle().fd(), F_SETFL, 0) != -1, "");
19	  }
20	
21	  void write(const std::string& buffer, const Network::Address::Instance& peer) {
22	    const auto rc = Network::Utility::writeToSocket(socket_->ioHandle(), Buffer::OwnedImpl(buffer),
23	                                                    nullptr, peer);
24	    ASSERT_EQ(rc.rc_, buffer.length());
25	  }
26	
27	  void recv(Network::UdpRecvData& datagram) {
28	    datagram = Network::UdpRecvData();
29	    const auto rc =
30	        Network::Test::readFromSocket(socket_->ioHandle(), *socket_->localAddress(), datagram);
31	    ASSERT_TRUE(rc.ok());
32	  }
33	
34	private:
35	  const Network::SocketPtr socket_;
36	};
