38	class UdpProxyIntegrationTest : public testing::TestWithParam<Network::Address::IpVersion>,
39	                                public BaseIntegrationTest {
40	public:
41	  UdpProxyIntegrationTest() : BaseIntegrationTest(GetParam(), configToUse()) {}
42	
43	  static std::string configToUse() {
44	    return ConfigHelper::BASE_UDP_LISTENER_CONFIG + R"EOF(
45	    listener_filters:
46	      name: envoy.filters.udp_listener.udp_proxy
47	      typed_config:
48	        '@type': type.googleapis.com/envoy.config.filter.udp.udp_proxy.v2alpha.UdpProxyConfig
49	        stat_prefix: foo
50	        cluster: cluster_0
51	      )EOF";
52	  }
53	
54	  void setup(uint32_t upstream_count) {
55	    udp_fake_upstream_ = true;
56	    if (upstream_count > 1) {
57	      setDeterministic();
58	      setUpstreamCount(upstream_count);
59	      config_helper_.addConfigModifier(
60	          [upstream_count](envoy::config::bootstrap::v3::Bootstrap& bootstrap) {
61	            for (uint32_t i = 1; i < upstream_count; i++) {
62	              bootstrap.mutable_static_resources()
63	                  ->mutable_clusters(0)
64	                  ->mutable_load_assignment()
65	                  ->mutable_endpoints(0)
66	                  ->add_lb_endpoints()
67	                  ->mutable_endpoint()
68	                  ->MergeFrom(ConfigHelper::buildEndpoint(
69	                      Network::Test::getLoopbackAddressString(GetParam())));
70	            }
71	          });
72	    }
73	    BaseIntegrationTest::initialize();
74	  }
75	
76	  /**
77	   *  Destructor for an individual test.
78	   */
79	  void TearDown() override {
80	    test_server_.reset();
81	    fake_upstreams_.clear();
82	  }
83	
84	  void requestResponseWithListenerAddress(const Network::Address::Instance& listener_address) {
85	    // Send datagram to be proxied.
86	    UdpSyncClient client(version_);
87	    client.write("hello", listener_address);
88	
89	    // Wait for the upstream datagram.
90	    Network::UdpRecvData request_datagram;
91	    ASSERT_TRUE(fake_upstreams_[0]->waitForUdpDatagram(request_datagram));
92	    EXPECT_EQ("hello", request_datagram.buffer_->toString());
93	
94	    // Respond from the upstream.
95	    fake_upstreams_[0]->sendUdpDatagram("world1", request_datagram.addresses_.peer_);
96	    Network::UdpRecvData response_datagram;
97	    client.recv(response_datagram);
98	    EXPECT_EQ("world1", response_datagram.buffer_->toString());
99	    EXPECT_EQ(listener_address.asString(), response_datagram.addresses_.peer_->asString());
100	
101	    EXPECT_EQ(5, test_server_->counter("udp.foo.downstream_sess_rx_bytes")->value());
102	    EXPECT_EQ(1, test_server_->counter("udp.foo.downstream_sess_rx_datagrams")->value());
103	    EXPECT_EQ(5, test_server_->counter("cluster.cluster_0.upstream_cx_tx_bytes_total")->value());
104	    EXPECT_EQ(1, test_server_->counter("cluster.cluster_0.udp.sess_tx_datagrams")->value());
105	
106	    EXPECT_EQ(6, test_server_->counter("cluster.cluster_0.upstream_cx_rx_bytes_total")->value());
107	    EXPECT_EQ(1, test_server_->counter("cluster.cluster_0.udp.sess_rx_datagrams")->value());
108	    // The stat is incremented after the send so there is a race condition and we must wait for
109	    // the counter to be incremented.
110	    test_server_->waitForCounterEq("udp.foo.downstream_sess_tx_bytes", 6);
111	    test_server_->waitForCounterEq("udp.foo.downstream_sess_tx_datagrams", 1);
112	
113	    EXPECT_EQ(1, test_server_->counter("udp.foo.downstream_sess_total")->value());
114	    EXPECT_EQ(1, test_server_->gauge("udp.foo.downstream_sess_active")->value());
115	  }
116	};
